#!/usr/bin/env python3
"""Independent test-only keys generated by system OpenSSH/OpenSSL, never user keys."""
from pathlib import Path
import base64,hashlib,hmac,json,os,struct,subprocess,textwrap
ROOT=Path(__file__).resolve().parent
os.umask(0o077)
def run(*args):return subprocess.check_output([str(x) for x in args],stderr=subprocess.PIPE)
def field(data):return struct.pack('>I',len(data))+data
def get(data,offset):
 n=struct.unpack('>I',data[offset:offset+4])[0];start=offset+4;return data[start:start+n],start+n

def parse(path):
 text=path.read_text();blob=base64.b64decode(''.join(text.splitlines()[1:-1]));assert blob.startswith(b'openssh-key-v1\0');offset=15
 cipher,offset=get(blob,offset);kdf,offset=get(blob,offset);opts,offset=get(blob,offset);assert cipher==b'none' and kdf==b'none';n=struct.unpack('>I',blob[offset:offset+4])[0];assert n==1;offset+=4
 public,offset=get(blob,offset);private,_=get(blob,offset);assert private[:4]==private[4:8];offset=8;algorithm,offset=get(private,offset)
 if algorithm==b'ssh-ed25519':
  point,offset=get(private,offset);secret,offset=get(private,offset);assert len(secret)==64 and secret[32:]==point;scalar=secret[:32]
 else:
  curve,offset=get(private,offset);point,offset=get(private,offset);scalar,offset=get(private,offset)
 return {'algorithm':algorithm,'public':public,'private':field(scalar),'scalar':scalar,'point':point,'blob':blob}
def pem(label,data):return '-----BEGIN '+label+'-----\n'+'\n'.join(textwrap.wrap(base64.b64encode(data).decode(),64))+'\n-----END '+label+'-----\n'
def ppk(key,version,public=None):
 public=key['public'] if public is None else public;comment=b'trueos-independent-fixture';algorithm=key['algorithm'];private=key['private'];payload=b''.join(field(x) for x in [algorithm,b'none',comment,public,private]);mac=hmac.new(hashlib.sha1(b'putty-private-key-file-mac-key').digest() if version==2 else b'',payload,hashlib.sha1 if version==2 else hashlib.sha256).hexdigest();pub=textwrap.wrap(base64.b64encode(public).decode(),64);priv=textwrap.wrap(base64.b64encode(private).decode(),64)
 return f'PuTTY-User-Key-File-{version}: {algorithm.decode()}\nEncryption: none\nComment: {comment.decode()}\nPublic-Lines: {len(pub)}\n'+'\n'.join(pub)+f'\nPrivate-Lines: {len(priv)}\n'+'\n'.join(priv)+'\nPrivate-MAC: '+mac+'\n'
manifest={'status':'generated by independent OpenSSH/OpenSSL; PPK writer follows RFCSSH string/MAC format and will be separately codec-validated','private_keys':'Test-only randomly generated keys, no user identities; directory mode0700/private files0600','families':{},'negative':{}}
ROOT.chmod(0o700)
for family,bits in [('ed25519',None),('p256',256),('p384',384),('p521',521)]:
 keypath=ROOT/(family+'.openssh');other=ROOT/(family+'.other.openssh')
 for target in [keypath,other]:
  if not target.exists():
   args=['ssh-keygen','-q','-t','ed25519' if bits is None else 'ecdsa','-N','','-C','trueos-independent-fixture','-f',target]
   if bits is not None:args+=['-b',str(bits)]
   run(*args)
 key=parse(keypath);otherkey=parse(other);canonical=run('ssh-keygen','-y','-f',keypath).decode().strip();(ROOT/(family+'.pub')).write_text(canonical+'\n');files=[keypath.name,family+'.pub']
 if bits is None:
  der=bytes.fromhex('302e020100300506032b657004220420')+key['scalar'];(ROOT/(family+'.pkcs8.der')).write_bytes(der);(ROOT/(family+'.pkcs8.pem')).write_text(pem('PRIVATE KEY',der));files += [family+'.pkcs8.der',family+'.pkcs8.pem']
  public=run('openssl','pkey','-in',ROOT/(family+'.pkcs8.pem'),'-pubout','-outform','DER');assert public[-32:]==key['point']
 else:
  named=ROOT/(family+'.sec1.named.pem');named.write_bytes(keypath.read_bytes());named.chmod(0o600);run('ssh-keygen','-p','-m','PEM','-P','','-N','','-f',named)
  run('openssl','ec','-in',named,'-param_enc','named_curve','-out',named)
  for kind in ['named','explicit']:
   sec1=ROOT/(family+'.sec1.'+kind+'.pem');run('openssl','ec','-in',named,'-param_enc','named_curve' if kind=='named' else 'explicit','-out',sec1)
   derpath=ROOT/(family+'.sec1.'+kind+'.der');run('openssl','ec','-in',sec1,'-outform','DER','-out',derpath)
   pkcs8=ROOT/(family+'.pkcs8.'+kind+'.pem');run('openssl','pkcs8','-topk8','-nocrypt','-in',sec1,'-out',pkcs8)
   pkcsder=ROOT/(family+'.pkcs8.'+kind+'.der');run('openssl','pkcs8','-topk8','-nocrypt','-in',sec1,'-outform','DER','-out',pkcsder)
   public=run('openssl','ec','-in',sec1,'-param_enc','named_curve','-pubout','-outform','DER');assert public.endswith(key['point'])
   files.extend([sec1.name,derpath.name,pkcs8.name,pkcsder.name])
  der=(ROOT/(family+'.sec1.named.der')).read_bytes();assert der.count(key['point'])==1;bad=der.replace(key['point'],otherkey['point']);path=ROOT/(family+'.sec1.mismatched-public.pem');path.write_text(pem('EC PRIVATE KEY',bad));manifest['negative'][path.name]='Valid scalar with another same-curve embedded public point; must not produce an inconsistent signing identity.'
 for version in [2,3]:
  target=ROOT/(family+f'.ppk{version}');target.write_text(ppk(key,version));files.append(target.name)
  bad=ROOT/(family+f'.ppk{version}.mismatched-public');bad.write_text(ppk(key,version,otherkey['public']));manifest['negative'][bad.name]='Valid PPK MAC, valid same-algorithm public key from different private scalar; test public/private consistency.'
  bad=ROOT/(family+f'.ppk{version}.bad-mac');s=ppk(key,version);bad.write_text(s[:-2]+('0' if s[-2]!='0' else '1')+'\n');manifest['negative'][bad.name]='Incorrect authenticated PPK MAC.'
 outer=key['blob'];offset=15
 for _ in range(3):_,offset=get(outer,offset)
 offset+=4;_,end=get(outer,offset);bad=outer[:offset]+field(otherkey['public'])+outer[end:];path=ROOT/(family+'.openssh.mismatched-public');path.write_text(pem('OPENSSH PRIVATE KEY',bad));manifest['negative'][path.name]='Outer OpenSSH public key differs from private section public key.'
 trunc=ROOT/(family+'.openssh.truncated');trunc.write_bytes(keypath.read_bytes()[:80]);manifest['negative'][trunc.name]='Truncated OpenSSH PEM.'
 manifest['families'][family]={'algorithm':key['algorithm'].decode(),'canonical_public_key':canonical,'ssh_public_blob_sha256':hashlib.sha256(key['public']).hexdigest(),'files':files}
for path in ROOT.iterdir():
 if path.is_file() and path.name!='manifest.json':path.chmod(0o600)
manifest['sha256']={p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(ROOT.iterdir()) if p.is_file() and p.name!='manifest.json'}
(ROOT/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n');print(json.dumps({'families':list(manifest['families']),'positive_files':sum(len(x['files']) for x in manifest['families'].values()),'negative_files':len(manifest['negative']),'manifest':str(ROOT/'manifest.json')},indent=2))
